"use server"

import { MarkdownReader } from "./markdown-reader"
import { MarkdownViewer } from "./markdown-viewer"

interface LectureViewerProps {
  filePath: string
  theme?: 'light' | 'dark'
}

export async function LectureViewer({ filePath, theme = 'light' }: LectureViewerProps) {
  const content = await MarkdownReader({ filePath })
  
  return (
    <MarkdownViewer content={content} theme={theme} />
  )
}